import{_ as t,a,c as i,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第一册：英语初阶 · Lesson 1 Excuse me!","description":"学习 be 动词的一般疑问句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 1 Excuse me!","description":"学习 be 动词的一般疑问句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 be 动词的一般疑问句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":false,"next":{"text":"第一册：英语初阶 · Lesson 2 Is this your ...?","link":"/life/english/new-concept/book-1/unit-01/lesson-002"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"第一册：英语初阶 · Lesson 2 Is this your ...?","link":"/life/english/new-concept/book-1/unit-01/lesson-002"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-01/lesson-001.md","filePath":"life/english/new-concept/book-1/unit-01/lesson-001.md"}'),s={name:"life/english/new-concept/book-1/unit-01/lesson-001.md"};function n(r,e,l,h,c,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-lesson-1-excuse-me" tabindex="-1">第一册：英语初阶 · Lesson 1 Excuse me! <a class="header-anchor" href="#第一册-英语初阶-·-lesson-1-excuse-me" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 1 Excuse me!&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-01/overview">单元 1</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-002">配套课 Lesson 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>礼貌确认身边物品的归属 本课要掌握be 动词的一般疑问句，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>excuse</td><td>/ɪkˈskjuːz/</td><td>v.</td><td>原谅；容许打扰</td><td>excuse me</td></tr><tr><td>bag</td><td>/bæɡ/</td><td>n.</td><td>包</td><td>a school bag</td></tr><tr><td>your</td><td>/jɔː/</td><td>限定词</td><td>你的；你们的</td><td>your bag</td></tr><tr><td>yes</td><td>/jes/</td><td>应答词</td><td>是的</td><td>yes, it is</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>excuse me — 引起注意时的礼貌开场</li><li>your bag — 用物主限定词说明归属</li></ul><h2 id="语法讲解-be-动词的一般疑问句" tabindex="-1">语法讲解：be 动词的一般疑问句 <a class="header-anchor" href="#语法讲解-be-动词的一般疑问句" aria-label="Permalink to &quot;语法讲解：be 动词的一般疑问句&quot;">​</a></h2><p>含 be 的陈述句变一般疑问句时，将 be 移到主语之前。this 指近处单数物品，回答时通常用 it。简短肯定回答必须保留 is，不能以 Yes, it&#39;s. 结尾。your 是物主限定词，后面接名词，不随物品的数量改变；礼貌开场和确认信息是两个不同的交际步骤。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Is this your ticket?</p></blockquote><p>这是你的票吗？</p><p>Is 是前置的系动词，this 是主语，your ticket 是表语；your 限定 ticket 的归属。回答时用 it 代替 this ticket。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>问句中的 this 不在回答中机械重复；用 Yes, it is.，不要写 Yes, this.</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“Is this your ticket?”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Is this your ticket? Is this your notebook?</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“礼貌确认身边物品的归属”写两至三句，再读给同伴听。至少使用一次be 动词的一般疑问句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Is 是前置的系动词，this 是主语，your ticket 是表语；your 限定 ticket 的归属。回答时用 it 代替 this ticket。 Is 前置形成问句，this 指近处的一件物品，your notebook 是表语。notebook 为单数，所以使用 is。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填入 be：___ this your ticket?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Is</p><p><strong>解析：</strong> 按本课规则判断：含 be 的陈述句变一般疑问句时，将 be 移到主语之前。this 指近处单数物品，回答时通常用 it。简短肯定回答必须保留 is，不能以 Yes, it&#39;s. 结尾。your 是物主限定词，后面接名词，不随物品的数量改变；礼貌开场和确认信息是两个不同的交际步骤。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“这是你的票吗？”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Is this your ticket?</p><p><strong>解析：</strong> Is 是前置的系动词，this 是主语，your ticket 是表语；your 限定 ticket 的归属。回答时用 it 代替 this ticket。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：Is this your notebook?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 这是你的笔记本吗？</p><p><strong>解析：</strong> Is 前置形成问句，this 指近处的一件物品，your notebook 是表语。notebook 为单数，所以使用 is。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：be 动词的一般疑问句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-002">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(s,[["render",n]]);export{p as __pageData,b as default};
